    window.__DSA__.css = "/* =============================================================================\n * dsh-task-alerts — browser half stylesheet (glassmorphism).\n *\n * Contract §8:\n *   root host container  -> .dsa-root   (data-dsa-scheme=\"light\" | \"dark\")\n *   panel                -> .dsa-panel\n *   toast                -> .dsa-toast\n *   six variables        -> --dsa-blur / --dsa-primary / --dsa-radius\n *                           --dsa-opacity / --dsa-tint / --dsa-tint-soft\n *\n * The client half overrides the six variables inline on .dsa-root from the\n * host state (config.ui). The defaults below are the contract defaults and are\n * what a bare .dsa-root renders with.\n *\n * `shell.overlay` is a click-through list slot (ui-layout), so the root host is\n * `pointer-events: none` and every interactive surface opts back in.\n * ========================================================================== */\n\n/* --------------------------------------------------------------------------\n * 1. Tokens\n * ----------------------------------------------------------------------- */\n\n.dsa-root {\n  --dsa-blur: 10px;            /* px — backdrop blur strength */\n  --dsa-primary: #87CEEB;      /* sky blue — the plugin accent */\n  --dsa-radius: 20px;          /* 16px..24px reads best; 20px is the shipped default */\n  --dsa-opacity: 0.7;          /* panel body opacity (0.05..1) */\n  --dsa-tint: #87CEEB;         /* gradient start */\n  --dsa-tint-soft: #E0F7FA;    /* gradient end */\n\n  --dsa-edge: 24px;            /* distance from the frame edges */\n  --dsa-stack-gap: 10px;\n  --dsa-ease: cubic-bezier(0.22, 0.61, 0.36, 1);\n\n  position: fixed;\n  inset: 0;\n  z-index: 2147483000;\n  pointer-events: none;        /* click-through by default */\n  color: #10222b;\n  font-family: inherit;\n  font-size: 13px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n}\n\n/* Fallback for engines without the `var()`-in-color-path resolution used below:\n   a solid translucent sky blue still reads as frosted glass, just flatter. */\n@supports not (backdrop-filter: blur(1px)) {\n  .dsa-root {\n    --dsa-blur: 0px;\n  }\n}\n\n/* --------------------------------------------------------------------------\n * 2. Panel — bottom-right, glass card\n * ----------------------------------------------------------------------- */\n\n.dsa-panel {\n  position: absolute;\n  right: var(--dsa-edge);\n  bottom: var(--dsa-edge);\n\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n\n  box-sizing: border-box;\n  width: max-content;\n  min-width: 280px;\n  max-width: min(420px, calc(100vw - 48px));\n  max-height: calc(100vh - 48px);\n  overflow: hidden auto;\n  padding: 14px 16px 12px;\n\n  background: linear-gradient(\n    135deg,\n    rgba(135, 206, 235, calc(var(--dsa-opacity) * 0.92)) 0%,\n    rgba(224, 247, 250, calc(var(--dsa-opacity) * 0.78)) 55%,\n    rgba(255, 255, 255, calc(var(--dsa-opacity) * 0.86)) 100%\n  );\n\n  backdrop-filter: blur(var(--dsa-blur)) saturate(1.55);\n  -webkit-backdrop-filter: blur(var(--dsa-blur)) saturate(1.55);\n\n  border: 1px solid rgba(255, 255, 255, 0.55);\n  border-radius: var(--dsa-radius);\n\n  box-shadow:\n    0 1px 0 rgba(255, 255, 255, 0.65) inset,\n    0 -1px 0 rgba(135, 206, 235, 0.22) inset,\n    0 6px 16px rgba(135, 206, 235, 0.20),\n    0 18px 44px rgba(56, 128, 168, 0.20),\n    0 2px 6px rgba(16, 34, 43, 0.10);\n\n  pointer-events: auto;\n  transition:\n    box-shadow 0.24s var(--dsa-ease),\n    transform 0.24s var(--dsa-ease),\n    opacity 0.24s var(--dsa-ease);\n\n  animation: dsa-rise-in 0.28s var(--dsa-ease) both;\n}\n\n.dsa-panel:hover {\n  box-shadow:\n    0 1px 0 rgba(255, 255, 255, 0.7) inset,\n    0 8px 20px rgba(135, 206, 235, 0.28),\n    0 24px 56px rgba(56, 128, 168, 0.26),\n    0 2px 8px rgba(16, 34, 43, 0.12);\n}\n\n/* --------------------------------------------------------------------------\n * 3. Dark scheme — same hue, compressed luminance\n * ----------------------------------------------------------------------- */\n\n[data-dsa-scheme=\"dark\"] {\n  color: #e6f4fa;\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-panel {\n  background: linear-gradient(\n    135deg,\n    rgba(64, 122, 150, calc(var(--dsa-opacity) * 0.92)) 0%,\n    rgba(28, 60, 76, calc(var(--dsa-opacity) * 0.9)) 58%,\n    rgba(18, 40, 52, calc(var(--dsa-opacity) * 0.94)) 100%\n  );\n  border-color: rgba(160, 216, 236, 0.28);\n  box-shadow:\n    0 1px 0 rgba(200, 238, 252, 0.14) inset,\n    0 -1px 0 rgba(135, 206, 235, 0.16) inset,\n    0 8px 22px rgba(0, 0, 0, 0.42),\n    0 22px 52px rgba(0, 0, 0, 0.34),\n    0 0 0 1px rgba(135, 206, 235, 0.08);\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-panel:hover {\n  box-shadow:\n    0 1px 0 rgba(200, 238, 252, 0.18) inset,\n    0 10px 26px rgba(0, 0, 0, 0.46),\n    0 26px 60px rgba(0, 0, 0, 0.38),\n    0 0 0 1px rgba(135, 206, 235, 0.12);\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-toast {\n  background: linear-gradient(\n    135deg,\n    rgba(64, 122, 150, calc(var(--dsa-opacity) * 0.9)) 0%,\n    rgba(26, 56, 72, calc(var(--dsa-opacity) * 0.92)) 100%\n  );\n  border-color: rgba(160, 216, 236, 0.24);\n  box-shadow:\n    0 1px 0 rgba(200, 238, 252, 0.12) inset,\n    0 8px 20px rgba(0, 0, 0, 0.38),\n    0 18px 40px rgba(0, 0, 0, 0.3);\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-btn {\n  background: rgba(214, 240, 250, 0.12);\n  border-color: rgba(180, 226, 244, 0.3);\n  color: #e6f4fa;\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-btn:hover {\n  box-shadow: 0 0 0 1px rgba(135, 206, 235, 0.4), 0 6px 16px rgba(0, 0, 0, 0.4);\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-btn--primary {\n  background: linear-gradient(135deg, rgba(135, 206, 235, 0.9), rgba(96, 168, 200, 0.88));\n  border-color: rgba(224, 247, 250, 0.5);\n  color: #08181f;\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-sub,\n[data-dsa-scheme=\"dark\"] .dsa-meta,\n[data-dsa-scheme=\"dark\"] .dsa-row-sub {\n  color: rgba(198, 230, 244, 0.72);\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-row {\n  background: rgba(214, 240, 250, 0.07);\n  border-color: rgba(180, 226, 244, 0.16);\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-badge {\n  background: rgba(135, 206, 235, 0.2);\n  border-color: rgba(180, 226, 244, 0.28);\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-path code {\n  background: rgba(0, 0, 0, 0.32);\n  border-color: rgba(180, 226, 244, 0.18);\n}\n\n/* --------------------------------------------------------------------------\n * 3b. Collapsed pill — the permanent panel entry point (contract §13.4)\n *\n * It sits in the SAME bottom-right corner as `.dsa-panel`, but both forms come\n * out of the same seat and are mutually exclusive, so they can never overlap.\n * The toast lives top-right, so nothing here can collide with it either.\n * `shell.overlay` is click-through, so the pill opts back in explicitly.\n * ----------------------------------------------------------------------- */\n\n.dsa-pill {\n  position: absolute;\n  right: var(--dsa-edge);\n  bottom: var(--dsa-edge);\n\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  box-sizing: border-box;\n  padding: 5px 8px 5px 12px;\n  min-height: 30px;\n\n  background: linear-gradient(\n    135deg,\n    rgba(135, 206, 235, calc(var(--dsa-opacity) * 0.92)) 0%,\n    rgba(224, 247, 250, calc(var(--dsa-opacity) * 0.78)) 58%,\n    rgba(255, 255, 255, calc(var(--dsa-opacity) * 0.88)) 100%\n  );\n\n  backdrop-filter: blur(var(--dsa-blur)) saturate(1.45);\n  -webkit-backdrop-filter: blur(var(--dsa-blur)) saturate(1.45);\n\n  border: 1px solid rgba(255, 255, 255, 0.55);\n  border-radius: 999px;\n\n  box-shadow:\n    0 1px 0 rgba(255, 255, 255, 0.62) inset,\n    0 4px 12px rgba(135, 206, 235, 0.26),\n    0 10px 26px rgba(56, 128, 168, 0.18);\n\n  color: #10222b;\n  font: inherit;\n  font-size: 12px;\n  line-height: 1.4;\n  cursor: pointer;\n  pointer-events: auto;        /* `shell.overlay` itself stays click-through */\n  transition:\n    transform 0.2s var(--dsa-ease),\n    box-shadow 0.2s var(--dsa-ease);\n  animation: dsa-rise-in 0.24s var(--dsa-ease) both;\n}\n\n.dsa-pill:hover {\n  transform: scale(1.04);\n  box-shadow:\n    0 1px 0 rgba(255, 255, 255, 0.7) inset,\n    0 6px 16px rgba(135, 206, 235, 0.34),\n    0 16px 34px rgba(56, 128, 168, 0.24);\n}\n\n.dsa-pill:active {\n  transform: scale(0.97);\n}\n\n.dsa-pill:focus-visible {\n  outline: 2px solid var(--dsa-primary);\n  outline-offset: 2px;\n}\n\n.dsa-pill-badge {\n  flex: 0 0 auto;\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n  background: rgba(120, 160, 180, 0.45);\n}\n\n.dsa-pill--pending .dsa-pill-badge {\n  background: #4C9EC4;\n}\n\n/* \"Still ringing\" is a soft halo, never a flash (contract §8/§11.6). */\n.dsa-pill--ring .dsa-pill-badge {\n  background: #2F80A8;\n  animation: dsa-ring-pulse 1.6s var(--dsa-ease) infinite;\n}\n\n.dsa-pill-text {\n  white-space: nowrap;\n}\n\n.dsa-pill-expand {\n  box-sizing: border-box;\n  margin-left: 2px;\n  padding: 3px 10px;\n  border: 1px solid rgba(255, 255, 255, 0.62);\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.55);\n  color: #0d3b4d;\n  font: inherit;\n  font-size: 12px;\n  cursor: pointer;\n  pointer-events: auto;\n  transition: background 0.2s var(--dsa-ease);\n}\n\n.dsa-pill-expand:hover {\n  background: rgba(255, 255, 255, 0.8);\n}\n\n.dsa-pill-expand:active {\n  background: rgba(255, 255, 255, 0.95);\n}\n\n.dsa-pill-expand:focus-visible {\n  outline: 2px solid var(--dsa-primary);\n  outline-offset: 2px;\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-pill {\n  background: linear-gradient(\n    135deg,\n    rgba(64, 122, 150, calc(var(--dsa-opacity) * 0.92)) 0%,\n    rgba(28, 60, 76, calc(var(--dsa-opacity) * 0.9)) 58%,\n    rgba(18, 40, 52, calc(var(--dsa-opacity) * 0.94)) 100%\n  );\n  border-color: rgba(160, 216, 236, 0.28);\n  color: #e6f4fa;\n  box-shadow:\n    0 1px 0 rgba(200, 238, 252, 0.14) inset,\n    0 6px 18px rgba(0, 0, 0, 0.4),\n    0 16px 34px rgba(0, 0, 0, 0.32);\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-pill-badge {\n  background: rgba(160, 216, 236, 0.45);\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-pill--pending .dsa-pill-badge,\n[data-dsa-scheme=\"dark\"] .dsa-pill--ring .dsa-pill-badge {\n  background: #7FD0EE;\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-pill-expand {\n  background: rgba(255, 255, 255, 0.12);\n  border-color: rgba(160, 216, 236, 0.28);\n  color: #e6f4fa;\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-pill-expand:hover {\n  background: rgba(255, 255, 255, 0.2);\n}\n\n/* Expanded panel with nothing pending (contract §13.4): states the fact, then\n   the recent-alert list follows. */\n.dsa-empty {\n  padding: 8px 10px;\n  border: 1px dashed rgba(135, 206, 235, 0.6);\n  border-radius: calc(var(--dsa-radius) * 0.5);\n  background: rgba(255, 255, 255, calc(var(--dsa-opacity) * 0.5));\n  color: #33596a;\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-empty {\n  background: rgba(0, 0, 0, 0.18);\n  border-color: rgba(160, 216, 236, 0.3);\n  color: #bcd9e6;\n}\n\n/* --------------------------------------------------------------------------\n * 4. Toast — top-right, compact glass stack\n * ----------------------------------------------------------------------- */\n\n.dsa-toast-stack {\n  position: absolute;\n  top: var(--dsa-edge);\n  right: var(--dsa-edge);\n  display: flex;\n  flex-direction: column;\n  align-items: flex-end;\n  gap: var(--dsa-stack-gap);\n  max-width: min(360px, calc(100vw - 48px));\n  pointer-events: none;        /* only the toast body is interactive */\n}\n\n.dsa-toast {\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n  box-sizing: border-box;\n  min-width: 220px;\n  max-width: min(360px, calc(100vw - 48px));\n  padding: 10px 12px;\n\n  background: linear-gradient(\n    135deg,\n    rgba(135, 206, 235, calc(var(--dsa-opacity) * 0.95)) 0%,\n    rgba(224, 247, 250, calc(var(--dsa-opacity) * 0.88)) 100%\n  );\n\n  backdrop-filter: blur(var(--dsa-blur)) saturate(1.5);\n  -webkit-backdrop-filter: blur(var(--dsa-blur)) saturate(1.5);\n\n  border: 1px solid rgba(255, 255, 255, 0.6);\n  border-radius: calc(var(--dsa-radius) * 0.6);\n\n  box-shadow:\n    0 1px 0 rgba(255, 255, 255, 0.6) inset,\n    0 4px 12px rgba(135, 206, 235, 0.22),\n    0 12px 28px rgba(56, 128, 168, 0.18),\n    0 1px 4px rgba(16, 34, 43, 0.1);\n\n  pointer-events: auto;\n  transition:\n    box-shadow 0.22s var(--dsa-ease),\n    transform 0.22s var(--dsa-ease),\n    opacity 0.22s var(--dsa-ease);\n\n  animation: dsa-drop-in 0.24s var(--dsa-ease) both;\n}\n\n.dsa-toast:hover {\n  box-shadow:\n    0 1px 0 rgba(255, 255, 255, 0.65) inset,\n    0 6px 16px rgba(135, 206, 235, 0.3),\n    0 16px 36px rgba(56, 128, 168, 0.24);\n}\n\n.dsa-toast-body {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  min-width: 0;\n}\n\n.dsa-toast-title {\n  font-size: 13px;\n  font-weight: 600;\n  letter-spacing: 0.01em;\n  overflow-wrap: anywhere;\n}\n\n.dsa-toast-msg {\n  font-size: 12px;\n  opacity: 0.82;\n  overflow-wrap: anywhere;\n  white-space: pre-wrap;\n}\n\n/* --------------------------------------------------------------------------\n * 5. Panel internals\n * ----------------------------------------------------------------------- */\n\n.dsa-header {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.dsa-title {\n  flex: 1 1 auto;\n  margin: 0;\n  font-size: 14px;\n  font-weight: 600;\n  letter-spacing: 0.01em;\n}\n\n.dsa-icon-btn {\n  flex: 0 0 auto;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 24px;\n  height: 24px;\n  padding: 0;\n  border: 1px solid transparent;\n  border-radius: calc(var(--dsa-radius) * 0.5);\n  background: rgba(255, 255, 255, 0.18);\n  color: inherit;\n  font: inherit;\n  font-size: 14px;\n  line-height: 1;\n  cursor: pointer;\n  transition: background 0.18s var(--dsa-ease), transform 0.18s var(--dsa-ease);\n}\n\n.dsa-icon-btn:hover {\n  background: rgba(255, 255, 255, 0.34);\n  transform: scale(1.04);\n}\n\n.dsa-icon-btn:active {\n  transform: scale(0.97);\n}\n\n.dsa-sub {\n  font-size: 12px;\n  opacity: 0.72;\n}\n\n.dsa-meta {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px 10px;\n  font-size: 12px;\n  opacity: 0.78;\n}\n\n.dsa-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  padding: 1px 7px;\n  border: 1px solid rgba(255, 255, 255, 0.5);\n  border-radius: 999px;\n  background: rgba(255, 255, 255, 0.32);\n  font-size: 11px;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n}\n\n.dsa-badge--live {\n  border-color: rgba(135, 206, 235, 0.6);\n  background: rgba(135, 206, 235, 0.28);\n}\n\n.dsa-badge--error {\n  border-color: rgba(214, 92, 92, 0.45);\n  background: rgba(214, 92, 92, 0.2);\n}\n\n.dsa-badge--success {\n  border-color: rgba(72, 170, 128, 0.45);\n  background: rgba(72, 170, 128, 0.2);\n}\n\n/* --------------------------------------------------------------------------\n * 5b. Ringing indicator (contract §11.6)\n * ----------------------------------------------------------------------- */\n\n.dsa-ring {\n  display: inline-block;\n  width: 7px;\n  height: 7px;\n  margin-right: 4px;\n  border-radius: 50%;\n  background: var(--dsa-primary);\n  box-shadow: 0 0 0 0 rgba(135, 206, 235, 0.6);\n  animation: dsa-ring-pulse 1.5s var(--dsa-ease) infinite;\n  flex: 0 0 auto;\n}\n\n/* The full status line: \"重复提醒中 · 第 N 次 · 每 M 秒\" */\n.dsa-ring-row {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n  padding: 5px 9px;\n  border: 1px solid rgba(135, 206, 235, 0.55);\n  border-radius: calc(var(--dsa-radius) * 0.55);\n  background: rgba(135, 206, 235, 0.2);\n  backdrop-filter: blur(var(--dsa-blur)) saturate(1.4);\n  -webkit-backdrop-filter: blur(var(--dsa-blur)) saturate(1.4);\n  font-size: 12px;\n  font-weight: 600;\n  letter-spacing: 0.01em;\n}\n\n.dsa-btn--ring {\n  border-color: rgba(135, 206, 235, 0.8);\n  box-shadow:\n    0 0 0 1px rgba(135, 206, 235, 0.6),\n    0 4px 14px rgba(135, 206, 235, 0.42);\n}\n\n.dsa-btn--ring:hover:not(:disabled) {\n  box-shadow:\n    0 0 0 1px rgba(135, 206, 235, 0.85),\n    0 8px 22px rgba(135, 206, 235, 0.55),\n    0 2px 6px rgba(16, 34, 43, 0.16);\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-ring {\n  box-shadow: 0 0 0 0 rgba(135, 206, 235, 0.5);\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-ring-row {\n  border-color: rgba(135, 206, 235, 0.42);\n  background: rgba(135, 206, 235, 0.16);\n}\n\n[data-dsa-scheme=\"dark\"] .dsa-btn--ring {\n  box-shadow:\n    0 0 0 1px rgba(135, 206, 235, 0.45),\n    0 4px 14px rgba(0, 0, 0, 0.4);\n}\n\n.dsa-card {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  padding: 9px 11px;\n  border: 1px solid rgba(255, 255, 255, 0.42);\n  border-radius: calc(var(--dsa-radius) * 0.7);\n  background: rgba(255, 255, 255, 0.24);\n}\n\n.dsa-card-title {\n  font-size: 12.5px;\n  font-weight: 600;\n  overflow-wrap: anywhere;\n}\n\n.dsa-card-msg {\n  font-size: 12px;\n  opacity: 0.82;\n  overflow-wrap: anywhere;\n  white-space: pre-wrap;\n}\n\n.dsa-list {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.dsa-row {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  padding: 7px 9px;\n  border: 1px solid rgba(255, 255, 255, 0.34);\n  border-radius: calc(var(--dsa-radius) * 0.55);\n  background: rgba(255, 255, 255, 0.16);\n}\n\n.dsa-row-main {\n  display: flex;\n  align-items: baseline;\n  gap: 6px;\n  font-size: 12.5px;\n  font-weight: 600;\n  overflow-wrap: anywhere;\n}\n\n.dsa-row-sub {\n  font-size: 11.5px;\n  opacity: 0.68;\n  overflow-wrap: anywhere;\n}\n\n.dsa-path {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 11.5px;\n}\n\n.dsa-path code {\n  flex: 1 1 auto;\n  min-width: 0;\n  padding: 2px 6px;\n  border: 1px solid rgba(255, 255, 255, 0.4);\n  border-radius: 6px;\n  background: rgba(255, 255, 255, 0.34);\n  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  font-size: 11px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  user-select: all;\n  cursor: text;\n}\n\n/* --------------------------------------------------------------------------\n * 6. Buttons\n * ----------------------------------------------------------------------- */\n\n.dsa-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin-top: 2px;\n}\n\n.dsa-btn {\n  flex: 0 1 auto;\n  padding: 6px 12px;\n  border: 1px solid rgba(255, 255, 255, 0.5);\n  border-radius: calc(var(--dsa-radius) * 0.5);\n  background: rgba(255, 255, 255, 0.28);\n  color: inherit;\n  font: inherit;\n  font-size: 12px;\n  font-weight: 600;\n  letter-spacing: 0.01em;\n  cursor: pointer;\n  transition:\n    transform 0.16s var(--dsa-ease),\n    box-shadow 0.16s var(--dsa-ease),\n    background 0.16s var(--dsa-ease),\n    opacity 0.16s var(--dsa-ease);\n}\n\n.dsa-btn:hover:not(:disabled) {\n  transform: scale(1.04);\n  box-shadow:\n    0 0 0 1px rgba(135, 206, 235, 0.55),\n    0 6px 16px rgba(135, 206, 235, 0.36),\n    0 2px 6px rgba(16, 34, 43, 0.12);\n}\n\n.dsa-btn:active:not(:disabled) {\n  transform: scale(0.97);\n  box-shadow: 0 0 0 1px rgba(135, 206, 235, 0.4);\n}\n\n.dsa-btn:focus-visible {\n  outline: 2px solid var(--dsa-tint);\n  outline-offset: 2px;\n}\n\n.dsa-btn--primary {\n  border-color: rgba(255, 255, 255, 0.72);\n  background: linear-gradient(135deg, rgba(135, 206, 235, 0.96), rgba(224, 247, 250, 0.92));\n  color: #0c2630;\n}\n\n.dsa-btn--primary:hover:not(:disabled) {\n  box-shadow:\n    0 0 0 1px rgba(135, 206, 235, 0.7),\n    0 8px 20px rgba(135, 206, 235, 0.46),\n    0 2px 6px rgba(16, 34, 43, 0.14);\n}\n\n.dsa-btn:disabled,\n.dsa-btn[aria-disabled=\"true\"] {\n  opacity: 0.45;\n  filter: grayscale(0.6);\n  cursor: not-allowed;\n  transform: none;\n  box-shadow: none;\n}\n\n/* --------------------------------------------------------------------------\n * 7. Motion\n * ----------------------------------------------------------------------- */\n\n@keyframes dsa-rise-in {\n  from {\n    opacity: 0;\n    transform: translateY(12px) scale(0.985);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0) scale(1);\n  }\n}\n\n@keyframes dsa-drop-in {\n  from {\n    opacity: 0;\n    transform: translateY(-8px) scale(0.985);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0) scale(1);\n  }\n}\n\n/* Soft pulse for the \"still ringing\" dot: grows a halo, never flashes. */\n@keyframes dsa-ring-pulse {\n  0% {\n    box-shadow: 0 0 0 0 rgba(135, 206, 235, 0.62);\n    opacity: 1;\n  }\n  70% {\n    box-shadow: 0 0 0 7px rgba(135, 206, 235, 0);\n    opacity: 0.72;\n  }\n  100% {\n    box-shadow: 0 0 0 0 rgba(135, 206, 235, 0);\n    opacity: 1;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .dsa-panel,\n  .dsa-toast,\n  .dsa-pill {\n    animation: none;\n  }\n\n  /* Contract §11.6: the pulse must never be the only carrier of \"still ringing\";\n     with motion reduced the dot stays solid and the text line says the rest. */\n  .dsa-ring,\n  .dsa-pill--ring .dsa-pill-badge {\n    animation: none;\n    box-shadow: none;\n    opacity: 1;\n  }\n\n  .dsa-panel,\n  .dsa-toast,\n  .dsa-pill,\n  .dsa-btn,\n  .dsa-icon-btn {\n    transition: none;\n  }\n\n  .dsa-pill:hover,\n  .dsa-btn:hover:not(:disabled),\n  .dsa-icon-btn:hover {\n    transform: none;\n  }\n\n  .dsa-pill:active,\n  .dsa-btn:active:not(:disabled),\n  .dsa-icon-btn:active {\n    transform: none;\n  }\n}\n\n/* --------------------------------------------------------------------------\n * 8. Narrow viewports\n * ----------------------------------------------------------------------- */\n\n@media (max-width: 520px) {\n  .dsa-root {\n    --dsa-edge: 12px;\n  }\n\n  .dsa-panel {\n    min-width: 0;\n    max-width: calc(100vw - 24px);\n  }\n\n  .dsa-toast-stack {\n    max-width: calc(100vw - 24px);\n  }\n\n  .dsa-toast {\n    min-width: 0;\n    max-width: calc(100vw - 24px);\n  }\n}\n\n/* --------------------------------------------------------------------------\n * 9. Settings page + sidebar action (contract §12.7)\n *\n * `.dsa-inline` is the in-flow twin of `.dsa-root`: the same six §8 variables,\n * but no fixed positioning, no z-index and no pointer-events tricks, because\n * these two seats render inside DSH's settings modal and sidebar foot rather\n * than inside the click-through overlay.\n * ----------------------------------------------------------------------- */\n\n.dsa-inline {\n  --dsa-blur: 10px;\n  --dsa-primary: #87CEEB;\n  --dsa-radius: 20px;\n  --dsa-opacity: 0.7;\n  --dsa-tint: #87CEEB;\n  --dsa-tint-soft: #E0F7FA;\n  --dsa-ease: cubic-bezier(0.22, 0.61, 0.36, 1);\n\n  color: #10222b;\n  font-family: inherit;\n  font-size: 13px;\n  line-height: 1.5;\n}\n\n.dsa-inline[data-dsa-scheme=\"dark\"] {\n  color: #e6f4fa;\n}\n\n@supports not (backdrop-filter: blur(1px)) {\n  .dsa-inline {\n    --dsa-blur: 0px;\n  }\n}\n\n/* --- settings page ------------------------------------------------------- */\n\n.dsa-settings {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  box-sizing: border-box;\n  width: 100%;\n  max-width: 640px;\n  padding: 14px 16px;\n\n  background: linear-gradient(\n    135deg,\n    rgba(135, 206, 235, calc(var(--dsa-opacity) * 0.5)) 0%,\n    rgba(224, 247, 250, calc(var(--dsa-opacity) * 0.42)) 55%,\n    rgba(255, 255, 255, calc(var(--dsa-opacity) * 0.58)) 100%\n  );\n\n  backdrop-filter: blur(var(--dsa-blur)) saturate(1.4);\n  -webkit-backdrop-filter: blur(var(--dsa-blur)) saturate(1.4);\n\n  border: 1px solid rgba(255, 255, 255, 0.55);\n  border-radius: var(--dsa-radius);\n\n  box-shadow:\n    0 1px 0 rgba(255, 255, 255, 0.6) inset,\n    0 6px 18px rgba(135, 206, 235, 0.18),\n    0 16px 40px rgba(56, 128, 168, 0.14);\n}\n\n.dsa-settings .dsa-header {\n  align-items: flex-start;\n}\n\n.dsa-status {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  justify-content: flex-end;\n}\n\n.dsa-fields {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n  gap: 10px 14px;\n}\n\n.dsa-group {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding: 10px 12px;\n  border: 1px solid rgba(255, 255, 255, 0.42);\n  border-radius: calc(var(--dsa-radius) * 0.7);\n  background: rgba(255, 255, 255, 0.2);\n}\n\n.dsa-group-title {\n  font-size: 12.5px;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n  opacity: 0.86;\n}\n\n.dsa-field {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n  min-width: 0;\n}\n\n.dsa-label {\n  font-size: 12px;\n  font-weight: 600;\n  letter-spacing: 0.01em;\n}\n\n.dsa-input {\n  box-sizing: border-box;\n  width: 100%;\n  padding: 5px 8px;\n  border: 1px solid rgba(255, 255, 255, 0.55);\n  border-radius: calc(var(--dsa-radius) * 0.45);\n  background: rgba(255, 255, 255, 0.5);\n  color: inherit;\n  font: inherit;\n  font-size: 12px;\n  transition: box-shadow 0.16s var(--dsa-ease), border-color 0.16s var(--dsa-ease);\n}\n\n.dsa-input:hover {\n  box-shadow: 0 0 0 1px rgba(135, 206, 235, 0.35);\n}\n\n.dsa-input:focus-visible {\n  outline: none;\n  border-color: var(--dsa-primary);\n  box-shadow: 0 0 0 1px rgba(135, 206, 235, 0.7), 0 4px 14px rgba(135, 206, 235, 0.35);\n}\n\n.dsa-field[data-dsa-invalid=\"true\"] .dsa-input {\n  border-color: rgba(214, 92, 92, 0.65);\n}\n\n/* --------------------------------------------------------------------------\n * Segmented choice group — the replacement for native <select>.\n *\n * Every option is always rendered in flow, so nothing depends on a popup layer:\n * it cannot be clipped by an ancestor's overflow and cannot come out as\n * same-colour text (both failure modes were observed with a native <select>).\n * ----------------------------------------------------------------------- */\n\n.dsa-choices {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 5px;\n  align-items: center;\n}\n\n.dsa-choice {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  position: relative;\n  box-sizing: border-box;\n  padding: 4px 9px;\n  border: 1px solid rgba(255, 255, 255, 0.55);\n  border-radius: calc(var(--dsa-radius) * 0.45);\n  background: rgba(255, 255, 255, 0.42);\n  color: inherit;\n  font-size: 12px;\n  line-height: 1.4;\n  cursor: pointer;\n  user-select: none;\n  transition:\n    box-shadow 0.16s var(--dsa-ease),\n    border-color 0.16s var(--dsa-ease),\n    transform 0.16s var(--dsa-ease);\n}\n\n.dsa-choice:hover {\n  transform: scale(1.03);\n  box-shadow: 0 0 0 1px rgba(135, 206, 235, 0.35), 0 4px 12px rgba(135, 206, 235, 0.22);\n}\n\n.dsa-choice:active {\n  transform: scale(0.98);\n}\n\n/* The real radio is kept for semantics and keyboard/AT behaviour, but is\n   visually replaced by the segmented surface (focus-visible still shows). */\n.dsa-choice-input {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  margin: -1px;\n  padding: 0;\n  border: 0;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n.dsa-choice:has(.dsa-choice-input:focus-visible) {\n  outline: none;\n  border-color: var(--dsa-primary);\n  box-shadow: 0 0 0 1px rgba(135, 206, 235, 0.7), 0 4px 14px rgba(135, 206, 235, 0.35);\n}\n\n.dsa-choice--on {\n  border-color: var(--dsa-primary);\n  background: linear-gradient(135deg, rgba(135, 206, 235, 0.55), rgba(224, 247, 250, 0.45));\n  box-shadow: 0 0 0 1px rgba(135, 206, 235, 0.55), 0 4px 14px rgba(135, 206, 235, 0.28);\n  font-weight: 600;\n}\n\n.dsa-inline[data-dsa-scheme=\"dark\"] .dsa-choice {\n  border-color: rgba(160, 216, 236, 0.3);\n  background: rgba(28, 60, 76, 0.55);\n}\n\n.dsa-inline[data-dsa-scheme=\"dark\"] .dsa-choice--on {\n  border-color: var(--dsa-primary);\n  background: linear-gradient(135deg, rgba(64, 122, 150, 0.75), rgba(28, 60, 76, 0.6));\n}\n\n/* Defensive: if a native <select> is ever reintroduced, at least pin the option\n   colours so the list can never come out as same-colour text. */\n.dsa-input option {\n  background-color: #ffffff;\n  color: #10222b;\n}\n\n.dsa-inline[data-dsa-scheme=\"dark\"] .dsa-input option {\n  background-color: #10303c;\n  color: #e6f4fa;\n}\n\n.dsa-switch {\n  width: 16px;\n  height: 16px;\n  margin: 2px 0 0;\n  accent-color: var(--dsa-primary);\n  cursor: pointer;\n}\n\n.dsa-switch:focus-visible {\n  outline: 2px solid var(--dsa-tint);\n  outline-offset: 2px;\n}\n\n.dsa-error {\n  font-size: 11.5px;\n  color: #a83a3a;\n}\n\n.dsa-hint {\n  font-size: 11.5px;\n  opacity: 0.72;\n  overflow-wrap: anywhere;\n}\n\n.dsa-hint--warn {\n  padding: 6px 9px;\n  border: 1px solid rgba(214, 158, 60, 0.5);\n  border-radius: calc(var(--dsa-radius) * 0.5);\n  background: rgba(214, 158, 60, 0.16);\n  opacity: 1;\n}\n\n.dsa-hint--ok {\n  padding: 6px 9px;\n  border: 1px solid rgba(72, 170, 128, 0.5);\n  border-radius: calc(var(--dsa-radius) * 0.5);\n  background: rgba(72, 170, 128, 0.16);\n  opacity: 1;\n}\n\n.dsa-hint--error {\n  padding: 6px 9px;\n  border: 1px solid rgba(214, 92, 92, 0.5);\n  border-radius: calc(var(--dsa-radius) * 0.5);\n  background: rgba(214, 92, 92, 0.14);\n  opacity: 1;\n}\n\n.dsa-badge--off {\n  border-color: rgba(140, 140, 140, 0.5);\n  background: rgba(140, 140, 140, 0.18);\n}\n\n.dsa-save {\n  border-color: rgba(135, 206, 235, 0.7);\n}\n\n.dsa-save:hover:not(:disabled) {\n  box-shadow:\n    0 0 0 1px rgba(135, 206, 235, 0.75),\n    0 8px 20px rgba(135, 206, 235, 0.42),\n    0 2px 6px rgba(16, 34, 43, 0.14);\n}\n\n/* --- sidebar-footer action ---------------------------------------------- */\n\n.dsa-sidebar-action {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  box-sizing: border-box;\n  padding: 5px 9px;\n  border: 1px solid rgba(255, 255, 255, 0.5);\n  border-radius: calc(var(--dsa-radius) * 0.5);\n  background: rgba(255, 255, 255, 0.26);\n  color: inherit;\n  font: inherit;\n  font-size: 12px;\n  font-weight: 600;\n  cursor: pointer;\n  transition:\n    transform 0.16s var(--dsa-ease),\n    box-shadow 0.16s var(--dsa-ease),\n    background 0.16s var(--dsa-ease);\n}\n\n.dsa-sidebar-action:hover {\n  transform: scale(1.04);\n  box-shadow:\n    0 0 0 1px rgba(135, 206, 235, 0.55),\n    0 6px 16px rgba(135, 206, 235, 0.36);\n}\n\n.dsa-sidebar-action:active {\n  transform: scale(0.97);\n}\n\n.dsa-sidebar-action:focus-visible {\n  outline: 2px solid var(--dsa-tint);\n  outline-offset: 2px;\n}\n\n.dsa-sidebar-action-icon {\n  font-size: 13px;\n  line-height: 1;\n}\n\n.dsa-sidebar-action-hint {\n  font-size: 10.5px;\n  font-weight: 500;\n  opacity: 0.66;\n}\n\n.dsa-sidebar-action--collapsed {\n  border-color: rgba(135, 206, 235, 0.6);\n  background: rgba(135, 206, 235, 0.2);\n}\n\n/* --- dark scheme -------------------------------------------------------- */\n\n.dsa-inline[data-dsa-scheme=\"dark\"] .dsa-settings {\n  background: linear-gradient(\n    135deg,\n    rgba(64, 122, 150, calc(var(--dsa-opacity) * 0.62)) 0%,\n    rgba(28, 60, 76, calc(var(--dsa-opacity) * 0.66)) 58%,\n    rgba(18, 40, 52, calc(var(--dsa-opacity) * 0.7)) 100%\n  );\n  border-color: rgba(160, 216, 236, 0.28);\n  box-shadow:\n    0 1px 0 rgba(200, 238, 252, 0.14) inset,\n    0 8px 22px rgba(0, 0, 0, 0.38),\n    0 20px 48px rgba(0, 0, 0, 0.3);\n}\n\n.dsa-inline[data-dsa-scheme=\"dark\"] .dsa-group {\n  border-color: rgba(180, 226, 244, 0.16);\n  background: rgba(214, 240, 250, 0.06);\n}\n\n.dsa-inline[data-dsa-scheme=\"dark\"] .dsa-input {\n  border-color: rgba(180, 226, 244, 0.28);\n  background: rgba(214, 240, 250, 0.1);\n}\n\n.dsa-inline[data-dsa-scheme=\"dark\"] .dsa-error {\n  color: #f0a3a3;\n}\n\n.dsa-inline[data-dsa-scheme=\"dark\"] .dsa-badge {\n  background: rgba(135, 206, 235, 0.2);\n  border-color: rgba(180, 226, 244, 0.28);\n}\n\n.dsa-inline[data-dsa-scheme=\"dark\"] .dsa-btn {\n  background: rgba(214, 240, 250, 0.12);\n  border-color: rgba(180, 226, 244, 0.3);\n  color: #e6f4fa;\n}\n\n.dsa-inline[data-dsa-scheme=\"dark\"] .dsa-btn--primary {\n  background: linear-gradient(135deg, rgba(135, 206, 235, 0.9), rgba(96, 168, 200, 0.88));\n  border-color: rgba(224, 247, 250, 0.5);\n  color: #08181f;\n}\n\n.dsa-inline[data-dsa-scheme=\"dark\"] .dsa-sidebar-action {\n  background: rgba(214, 240, 250, 0.12);\n  border-color: rgba(180, 226, 244, 0.3);\n}\n\n.dsa-inline[data-dsa-scheme=\"dark\"] .dsa-sidebar-action--collapsed {\n  border-color: rgba(135, 206, 235, 0.45);\n  background: rgba(135, 206, 235, 0.18);\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .dsa-sidebar-action,\n  .dsa-input {\n    transition: none;\n  }\n\n  .dsa-sidebar-action:hover,\n  .dsa-sidebar-action:active {\n    transform: none;\n  }\n}\n";

